/* Guided examples are ephemeral and never touch SoloStore or real game state. */
(() => {
  'use strict';
  const game=document.body.dataset.soloGame,dice=game==='dice',C=SoloCore,L=LearningCore;
  if(!['dice','line'].includes(game))return;
  const name=dice?'전략 주사위':'라인 컨트롤',lessons=dice?L.diceLessons:L.lineLessons;
  const dialog=document.createElement('dialog');dialog.id='board-picture-practice';dialog.setAttribute('aria-labelledby','board-practice-title');document.body.appendChild(dialog);
  let step=0,board=[],selected=null,preview=null,solved=false,settled=false,message='';
  const p=()=>lessons[step],pos=(i,n)=>`${Math.floor(i/n)+1}행 ${i%n+1}열`;
  function reset(){board=dice?L.lessonBoard(p().cells,9,null):L.lessonBoard([...p().human.map(i=>[i,1]),...p().ai.map(i=>[i,2])],25,0);selected=null;preview=null;solved=false;settled=false;message='';render();}
  function diceView(){const score=C.diceScore(board);return `<p>${p().guide}</p><div class="practice-dice-pair" role="group" aria-label="연습 주사위 선택">${p().pair.map((value,i)=>`<button type="button" data-learn-die="${i}" aria-pressed="${selected===i}" ${solved?'disabled':''}><span class="practice-die-face">${['','⚀','⚁','⚂','⚃','⚄','⚅'][value]}</span><b>${value} 선택</b></button>`).join('')}</div><div class="practice-dice-board" role="group" aria-label="연습용 3행 3열 주사위 보드">${board.map((value,i)=>`<button type="button" data-learn-dice-cell="${i}" class="${i===p().target?'practice-target':''} ${preview?.index===i?'practice-selected':''}" aria-label="연습 ${pos(i,3)} ${value===null?'빈칸':value}${i===p().target?' · 여기에 놓아보세요':''}" ${solved||value!==null?'disabled':''}>${value===null?'＋':value}${i===p().target&&!solved?'<small>놓아보기</small>':''}</button>`).join('')}</div><p class="practice-score-total">현재 점수 ${score.total}점 = 눈의 합 ${score.base}점 + 보너스 ${score.total-score.base}점</p>${preview?`<div class="practice-preview" role="status">${pos(preview.index,3)}에 ${preview.value} 배치 예상: <b>+${preview.delta}점</b><br>눈의 합 +${preview.base}점${preview.gains.map(g=>` · ${g.label} 보너스 +${g.points}점`).join('')}<br>예상 총점 ${preview.total}점<button type="button" class="primary" data-learn-dice-confirm>이 칸에 배치하기</button></div>`:''}`;}
  function lineView(){const scores=C.lineScore(board),human=scores[0],ai=scores[1];return `<p>${p().guide}</p><p class="note">규칙만 떼어 배우는 예시 보드입니다. 연습에서는 AI가 움직이지 않아요.</p><div class="practice-line-wrap"><div class="line-board practice-line-board" role="group" aria-label="연습용 5행 5열 라인 보드">${board.map((n,i)=>`<button type="button" data-learn-line-cell="${i}" class="line-cell ${n===1?'human':n===2?'ai':''} ${i%5>=1&&i%5<=3&&Math.floor(i/5)>=1&&Math.floor(i/5)<=3?'central':''} ${i===p().target?'practice-target':''}" aria-label="연습 ${pos(i,5)} ${n===1?'내 돌':n===2?'AI 돌':'빈칸'}${i===p().target&&!solved?' · 여기에 놓아보세요':''}" ${n||solved?'disabled':''}>${n===1?'●':n===2?'◆':'＋'}</button>`).join('')}</div><svg class="line-score-overlay" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${scores.flatMap((s,player)=>s.lines.map(id=>`<line class="score-connection player-${player+1} recent-score" data-lesson-line="${id}"/>`)).join('')}</svg></div><p class="note">실선 ● 나 · 점선 ◆ AI · 연한 중앙 9칸은 종료 때 돌당 +1점</p><p class="practice-score-total">나 ${human.linePoints+(settled?human.center:0)}점 · AI ${ai.linePoints+(settled?ai.center:0)}점</p><p>${settled?`경기 종료 계산: 나 연결 ${human.linePoints}점 + 중앙 ${human.center}칸 × 1점 = ${human.total}점 / AI 연결 ${ai.linePoints}점 + 중앙 ${ai.center}칸 × 1점 = ${ai.total}점`:`중앙 보너스는 아직 합산하지 않아요. 종료 때 나 +${human.center}점 / AI +${ai.center}점`}</p>${p().goal==='center'&&solved&&!settled?'<button type="button" class="primary" data-learn-settle>경기 종료 점수 계산해보기</button>':''}`;}
  function positionLines(){if(dice)return;const grid=dialog.querySelector('.practice-line-board'),r=grid.getBoundingClientRect();if(!r.width)return;dialog.querySelectorAll('[data-lesson-line]').forEach(line=>{const cells=C.lineWindows[+line.dataset.lessonLine];for(const [key,index] of [['1',cells[0]],['2',cells[2]]]){const b=grid.querySelector(`[data-learn-line-cell="${index}"]`).getBoundingClientRect();line.setAttribute('x'+key,(b.left+b.width/2-r.left)/r.width*100);line.setAttribute('y'+key,(b.top+b.height/2-r.top)/r.height*100);}});}
  function render(){const done=solved&&(p().goal!=='center'||settled);dialog.innerHTML=`<div class="dialog-head"><span>그림으로 배우기 · ${step+1}/${lessons.length}</span><button type="button" data-board-close aria-label="${name} 연습 닫기">닫기</button></div><h2 id="board-practice-title" tabindex="-1">${name} · 그림 연습</h2><p class="practice-note">시간·횟수 제한 없이 연습해요. 실제 진행과 완료 기록은 그대로 유지됩니다. 다시 하기로 언제든 같은 예시를 반복할 수 있어요.</p><h3>${p().title}</h3>${dice?diceView():lineView()}<p class="light-practice-status" role="status" aria-live="polite">${message||'점선으로 표시된 칸을 살펴보고 직접 눌러보세요.'}</p><div class="actions practice-actions"><button type="button" data-board-reset>이 연습 다시 하기</button>${done&&step<lessons.length-1?'<button type="button" class="primary" data-board-next>다음 연습 →</button>':''}</div><button type="button" class="practice-entry light-return" data-board-close>${done&&step===lessons.length-1?'연습 완료 · 실제 게임으로 돌아가기':'실제 게임으로 돌아가기'}</button>`;positionLines();}
  dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
    if(b.hasAttribute('data-board-close'))dialog.close();
    else if(b.hasAttribute('data-board-reset')){reset();dialog.querySelector('h2').focus();}
    else if(b.hasAttribute('data-board-next')){step++;reset();dialog.querySelector('h2').focus();}
    else if(b.hasAttribute('data-learn-die')){selected=+b.dataset.learnDie;preview=null;message='표시된 빈칸을 눌러 예상 점수를 확인해보세요.';render();}
    else if(b.hasAttribute('data-learn-dice-cell')){if(selected===null){message='먼저 주사위 하나를 골라주세요.';render();return;}preview=L.previewDice(board,p().pair[selected],+b.dataset.learnDiceCell,C.diceScore);message='예상 점수를 보고 배치를 확정해보세요. 확정 전에는 주사위와 칸을 바꿀 수 있어요.';render();}
    else if(b.hasAttribute('data-learn-dice-confirm')&&preview){if(preview.index!==p().target||(p().goal!=='base'&&!preview.gains.some(g=>g.key===p().goal))){message='이번에는 표시된 줄의 보너스를 만들어봐요. 보드에는 놓지 않았어요. 다른 주사위나 표시된 칸으로 다시 시도해보세요.';preview=null;render();return;}board[preview.index]=preview.value;message=`배치 완료! 눈의 합 +${preview.base}점${preview.gains.map(g=>` + ${g.label} 보너스 ${g.points}점`).join('')} = +${preview.delta}점. 실제 기록에는 포함되지 않아요.`;preview=null;solved=true;render();}
    else if(b.hasAttribute('data-learn-line-cell')){const i=+b.dataset.learnLineCell;if(i!==p().target){message='이번에는 점선 칸에 놓아 표시된 규칙을 연습해보세요. 다른 칸에는 돌을 놓지 않았어요.';render();return;}const before=C.lineScore(board)[0];board[i]=1;const after=C.lineScore(board)[0],newLines=after.lines.filter(id=>!before.lines.includes(id));solved=true;message=p().goal==='center'?'중앙에 돌을 놓았어요. 아직 점수에는 넣지 않고, 종료 계산에서 더해요.':`${newLines.map(id=>{const w=C.lineWindows[id];return `${pos(w[0],5)} → ${pos(w[2],5)} +3점`;}).join(' / ')} · 이번 수 +${after.linePoints-before.linePoints}점. 연결 총 ${after.linePoints}점.`;render();}
    else if(b.hasAttribute('data-learn-settle')){settled=true;message='종료할 때만 중앙의 자기 돌을 세어 점수에 더했어요. 연습 결과는 실제 기록에 포함되지 않아요.';render();}
  });
  const observer=window.ResizeObserver?new ResizeObserver(positionLines):null;observer?.observe(dialog);
  function open(){step=0;reset();dialog.showModal();positionLines();dialog.querySelector('h2').focus();}
  const button=document.createElement('button');button.type='button';button.className='practice-entry';button.textContent='시간제한 없는 그림 연습';button.addEventListener('click',open);document.querySelector('.solo-tools').prepend(button);
  if(new URLSearchParams(location.search).get('practice')==='1')open();
})();
